package com.yjiyun.chatflows.runtime.security;
import io.agentscope.core.agent.RuntimeContext; import io.agentscope.core.permission.*; import io.agentscope.harness.agent.HarnessAgent; import java.util.*; import java.util.concurrent.*;
public final class TenantToolPermissions { private record Rules(Set<String> allow,Set<String> deny){} private final Map<String,Rules> rules=new ConcurrentHashMap<>();
 public void configure(String client,Collection<String> allow,Collection<String> deny){rules.put(client,new Rules(Set.copyOf(allow),Set.copyOf(deny)));}
 public void grant(String client,Collection<String> tools){configure(client,tools,List.of());}
 public void install(HarnessAgent agent,RuntimeContext rc,String client){Rules r=rules.getOrDefault(client,new Rules(Set.of(),Set.of()));PermissionContextState.Builder b=PermissionContextState.builder().mode(PermissionMode.DONT_ASK);Set<String> registered=agent.getDelegate().getToolkit().getToolNames();for(String tool:registered){boolean permitted=r.allow().contains(tool)&&!r.deny().contains(tool);PermissionRule rule=new PermissionRule(tool,null,permitted?PermissionBehavior.ALLOW:PermissionBehavior.DENY,"agent_blueprint");if(permitted)b.addAllowRule(tool,rule);else b.addDenyRule(tool,rule);}agent.getDelegate().replacePermissionContext(rc.getUserId(),rc.getSessionId(),b.build());}
 public void require(String client,String tool){if(!allowed(client,tool))throw new SecurityException("tool denied for tenant: "+tool);} public boolean allowed(String client,String tool){Rules r=rules.get(client);return r!=null&&r.allow().contains(tool)&&!r.deny().contains(tool);} }
